import re

# Parse dialogs to separate agent messages from customer messages
def parse_dialog(entry):
    """Parse a dialog into customer and agent messages"""
    company_id = entry['company_id']
    dialog_text = entry['dialog']

    # Split into individual messages
    messages = dialog_text.split('\n\n')

    agent_messages = []
    customer_messages = []

    for msg in messages:
        if msg.startswith(company_id):
            agent_messages.append(msg)
        else:
            customer_messages.append(msg)

    return customer_messages, agent_messages

# Check if agent apologizes
def agent_apologizes(agent_messages):
    apology_patterns = ['sorry', 'apologize', 'apologies', 'apology', 'apologise', 'sincerest apologies']
    text = ' '.join(agent_messages).lower()
    for pattern in apology_patterns:
        if pattern in text:
            return True
    return False

